"""Oxford-IIIT Pet loading and fixed, auditable experiment splits."""

from __future__ import annotations

import random
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Sequence

import torch
from torch.utils.data import DataLoader, Dataset
from torchvision.datasets import OxfordIIITPet

from src.preprocessing import preprocess_pair


PROJECT_ROOT = Path(__file__).resolve().parents[1]
EXPECTED_DEVELOPMENT_SIZE = 3680
EXPECTED_TEST_SIZE = 3669


def _sample_ids(source: OxfordIIITPet) -> list[str]:
    """Inspect paths generated by torchvision from the official split file.

    Torchvision exposes no public sample-ID API; its ``_images`` and ``_segs``
    lists are checked here so a future dataset implementation change fails
    clearly instead of silently misaligning split records.
    """

    images = getattr(source, "_images", None)
    masks = getattr(source, "_segs", None)
    if images is None or masks is None or len(images) != len(source) or len(masks) != len(source):
        raise RuntimeError("Unexpected torchvision OxfordIIITPet path layout")
    ids: list[str] = []
    for image_name, mask_name in zip(images, masks):
        image_path, mask_path = Path(image_name), Path(mask_name)
        if image_path.stem != mask_path.stem:
            raise RuntimeError(f"Unpaired pet image and trimap: {image_path} / {mask_path}")
        if not image_path.is_file() or not mask_path.is_file():
            raise FileNotFoundError(f"Missing pet image or trimap: {image_path} / {mask_path}")
        ids.append(image_path.stem)
    if len(ids) != len(set(ids)):
        raise RuntimeError("Duplicate Oxford-IIIT Pet sample IDs")
    return ids


def make_train_validation_ids(
    development_ids: Sequence[str], *, validation_ratio: float, seed: int
) -> tuple[list[str], list[str]]:
    """Deterministically partition official ``trainval`` IDs without test data."""

    if not 0 < validation_ratio < 1:
        raise ValueError("validation_ratio must be between zero and one")
    if len(development_ids) != len(set(development_ids)):
        raise ValueError("development IDs must be unique")
    shuffled = list(development_ids)
    random.Random(seed).shuffle(shuffled)
    validation_count = round(len(shuffled) * validation_ratio)
    if not 0 < validation_count < len(shuffled):
        raise ValueError("validation split must contain at least one sample")
    # Keep the persisted files in the official annotation order for review.
    validation_set = set(shuffled[:validation_count])
    train_ids = [sample_id for sample_id in development_ids if sample_id not in validation_set]
    validation_ids = [sample_id for sample_id in development_ids if sample_id in validation_set]
    return train_ids, validation_ids


def _read_or_write_split(path: Path, expected: Sequence[str]) -> list[str]:
    if path.is_file():
        stored = [line.strip() for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
        if stored != list(expected):
            raise ValueError(
                f"Persisted split {path} differs from the configured seed or source data. "
                "Review it before replacing split records."
            )
        return stored
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(expected) + "\n", encoding="utf-8")
    return list(expected)


def _load_source(root: Path, split: str, download: bool) -> OxfordIIITPet:
    try:
        return OxfordIIITPet(
            root=str(root), split=split, target_types="segmentation", download=download
        )
    except Exception as exc:
        action = "download or load" if download else "load"
        raise RuntimeError(
            f"Could not {action} the Oxford-IIIT Pet {split} split in {root}. "
            "Check the dataset directory and network connection."
        ) from exc


@dataclass(frozen=True)
class PreparedData:
    """Validated sources and indices for one fixed experiment split."""

    train_source: OxfordIIITPet
    test_source: OxfordIIITPet | None
    train_indices: tuple[int, ...]
    validation_indices: tuple[int, ...]
    train_ids: tuple[str, ...]
    validation_ids: tuple[str, ...]
    test_ids: tuple[str, ...]
    image_size: int
    batch_size: int
    seed: int


def prepare_data(
    config: dict[str, Any],
    *,
    download: bool = True,
    include_test: bool = False,
    project_root: Path | None = None,
) -> PreparedData:
    """Load official split metadata, verify pairs, and persist memberships.

    The held-out test source is opened only with ``include_test=True``. Normal
    training and PSO calls therefore cannot accidentally inspect test samples.
    """

    base = Path(project_root) if project_root is not None else PROJECT_ROOT
    settings = config["dataset"]
    root = Path(settings["root"])
    if not root.is_absolute():
        root = base / root
    seed = int(config["project"]["seed"])
    development = _load_source(root, "trainval", download)
    development_ids = _sample_ids(development)
    if len(development_ids) != EXPECTED_DEVELOPMENT_SIZE:
        raise RuntimeError(
            f"Official development split should have {EXPECTED_DEVELOPMENT_SIZE} samples; "
            f"found {len(development_ids)}"
        )

    train_ids, validation_ids = make_train_validation_ids(
        development_ids,
        validation_ratio=float(settings["validation_ratio"]),
        seed=seed,
    )
    split_root = base / "splits"
    train_ids = _read_or_write_split(split_root / "train.txt", train_ids)
    validation_ids = _read_or_write_split(split_root / "validation.txt", validation_ids)
    if len(train_ids) != 2944 or len(validation_ids) != 736:
        raise RuntimeError("Configured development split must contain 2944 train and 736 validation samples")
    if set(train_ids) & set(validation_ids):
        raise RuntimeError("Training and validation splits overlap")

    test_source = None
    test_ids: list[str] = []
    if include_test:
        test_source = _load_source(root, "test", download)
        test_ids = _sample_ids(test_source)
        if len(test_ids) != EXPECTED_TEST_SIZE:
            raise RuntimeError(
                f"Official test split should have {EXPECTED_TEST_SIZE} samples; found {len(test_ids)}"
            )
        test_ids = _read_or_write_split(split_root / "test.txt", test_ids)
        if (set(train_ids) | set(validation_ids)) & set(test_ids):
            raise RuntimeError("Development and held-out test splits overlap")

    id_to_index = {sample_id: index for index, sample_id in enumerate(development_ids)}
    return PreparedData(
        train_source=development,
        test_source=test_source,
        train_indices=tuple(id_to_index[sample_id] for sample_id in train_ids),
        validation_indices=tuple(id_to_index[sample_id] for sample_id in validation_ids),
        train_ids=tuple(train_ids),
        validation_ids=tuple(validation_ids),
        test_ids=tuple(test_ids),
        image_size=int(settings["image_size"]),
        batch_size=int(settings["batch_size"]),
        seed=seed,
    )


class OxfordPetBinaryDataset(Dataset[tuple[torch.Tensor, torch.Tensor, torch.Tensor]]):
    """View of a torchvision split returning image, foreground, valid mask."""

    def __init__(
        self,
        source: OxfordIIITPet,
        indices: Sequence[int],
        image_size: int,
        *,
        augment: bool = False,
    ) -> None:
        self.source = source
        self.indices = tuple(indices)
        self.image_size = image_size
        self.augment = augment
        if any(index < 0 or index >= len(source) for index in self.indices):
            raise IndexError("Dataset subset index is out of range")

    def __len__(self) -> int:
        return len(self.indices)

    def __getitem__(self, index: int) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        image, trimap = self.source[self.indices[index]]
        return preprocess_pair(image, trimap, self.image_size, augment=self.augment)


def create_dataloaders(
    config: dict[str, Any],
    *,
    download: bool = True,
    num_workers: int = 0,
    include_test: bool = False,
    project_root: Path | None = None,
) -> tuple[DataLoader, DataLoader, DataLoader | None]:
    """Build loaders with shared preprocessing and a held-out optional test."""

    prepared = prepare_data(
        config, download=download, include_test=include_test, project_root=project_root
    )
    common = {"batch_size": prepared.batch_size, "num_workers": num_workers}
    train = DataLoader(
        OxfordPetBinaryDataset(
            prepared.train_source, prepared.train_indices, prepared.image_size, augment=True
        ),
        shuffle=True,
        generator=torch.Generator().manual_seed(prepared.seed),
        **common,
    )
    validation = DataLoader(
        OxfordPetBinaryDataset(
            prepared.train_source, prepared.validation_indices, prepared.image_size
        ),
        shuffle=False,
        **common,
    )
    test = None
    if include_test and prepared.test_source is not None:
        test = DataLoader(
            OxfordPetBinaryDataset(
                prepared.test_source, range(len(prepared.test_source)), prepared.image_size
            ),
            shuffle=False,
            **common,
        )
    return train, validation, test
